using System.Security.Claims;using System.Text;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;namespace ExamGateway.Extensions;public static class GatewayServiceExtensions{public static IServiceCollection AddGateway(this IServiceCollection s,IConfiguration c){s.AddEndpointsApiExplorer();s.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="WAEC API Gateway API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});var jwt=c.GetSection("Jwt");var key=jwt["Key"]??throw new InvalidOperationException("Jwt:Key must be configured.");if(Encoding.UTF8.GetByteCount(key)<32)throw new InvalidOperationException("Jwt:Key must contain at least 32 UTF-8 bytes.");s.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=jwt["Issuer"],ValidateAudience=true,ValidAudience=jwt["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30),NameClaimType=ClaimTypes.Name,RoleClaimType=ClaimTypes.Role});s.AddAuthorization(o=>{o.AddPolicy("CatalogRead",p=>p.RequireClaim("permission","catalog.read"));o.AddPolicy("CatalogManage",p=>p.RequireClaim("permission","catalog.manage"));o.AddPolicy("RegistrationsRead",p=>p.RequireClaim("permission","registrations.read"));o.AddPolicy("RegistrationsCreate",p=>p.RequireClaim("permission","registrations.create"));o.AddPolicy("Authenticated",p=>p.RequireAuthenticatedUser());});s.AddReverseProxy().LoadFromConfig(c.GetSection("ReverseProxy"));return s;}}